unter:["🔍","☝️ Swap a rival’s member for a shop one, same cost or more"],patriarch:["👴","🏁 +1 follower per 2 members"],panel:["🪧","✨ Promote or demote another of your members"],proselytizers:["📣","♾️ You recruit: +1 follower"],mentor:["🧑‍🏫","✨ Recruit the cheapest shop member"],mob:["🔥","🌙 +2 followers per rival with fewer red members"],encore:["👏","☝️ Your next On Recruit happens twice"],impressionist:["🖼️","♾️ Anyone copies an action: +1 of its color"],agents:["🕶️","♾️ Rivals can’t copy your actions"],bait:["🪝","♾️ Anyone copies your action: they −1 follower, you +1 follower"],roadie:["🎚️","✨🌅 +1 green per green member"],busker:["🪕","✨🌅 +2 green"],understudy:["🎟️","✨ Copy the last turn’s action"],impersonator:["🎭","✨🌅 Copy a rival member’s ability"],chronicler:["📜","🏁 +1 follower per green member"],doppelganger:["👯","✨ Becomes a copy of another of your members"],ensemble:["🎶","♾️ You copy your own action: +1 follower"],"stunt-double":["🤸","✨ Copy the action you just took"],"fan-club":["📸","✨ Copy an action the follower leader has a minion on"],impostors:["🥸","✨ Becomes a copy of a rival’s member"],wallflower:["🌼","♾️ Your copied actions give double"],"tribute-band":["🎸","☝️ Do every action one rival is on this round"],"second-story-man":["🪜","🌙 Before contests: steal 2 from a rival"],fence:["🚧","♾️ A rival steals from you: +2 magenta"],accomplice:["🦹","✨ Steal 3"],crew:["🏴‍☠️",""],cutpurse:["🤏","✨🌅 Steal 1 from the richest rival"],"robin-hood":["🏹","♾️ Steal from the follower leader: +1 follower"],snitch:["🐀","♾️ A rival steals from you: they −1 follower"],"sticky-fingers":["🍯","♾️ Your steals take 1 more"],kidnapper:["🧳","✨🌅 Steal the cheapest member of the biggest cult"],desperado:["🌵","♾️ Fewest followers: your steals take 2 more"],fixer:["💼","☝️ Pay magenta equal to a rival member’s cost to steal it"],shoplifter:["🛍️","♾️ You recruit: steal 1"],bodyguards:["💪","♾️ Rivals can’t steal from you"],"double-agent":["🕵️","✨ Trade this member for one of a rival’s"],ex